Testing kNN consistency, spiral phase and sinusoidal grids.
```python
X=np.load("train_x.npy"); Y=np.load("train_y.npy").astype(int)
from scipy.spatial.distance import cdist
D=cdist(X,X); np.fill_diagonal(D,9)
for k in [1,3,5]:
    nn=np.argsort(D,1)[:,:k]; p=(Y[nn].mean(1)>0.5).astype(int); print('knn',k,(p==Y).mean())
r=np.hypot(X[:,0],X[:,1]); th=np.arctan2(X[:,1],X[:,0])
best=[]
for k in np.linspace(-15,15,301):
  for m in [1,2]:
    ph=(m*th - k*r)
    for off in np.linspace(0,2*np.pi,24,endpoint=False):
        p=(np.sin(ph+off)>0).astype(int); best.append(((p==Y).mean(),k,m,off))
best.sort(reverse=True); print(best[:5])
b2=[]
for a in np.linspace(0.5,8,31):
  for c in np.linspace(0.5,8,31):
    for f in ['ss','s+s']:
      for o1 in [0,np.pi/2]:
        for o2 in [0,np.pi/2]:
          v=np.sin(a*X[:,0]+o1)*np.sin(c*X[:,1]+o2) if f=='ss' else np.sin(a*X[:,0]+o1)+np.sin(c*X[:,1]+o2)
          for s in [0,1]:
            p=((v>0)^s).astype(int); b2.append(((p==Y).mean(),a,c,f,o1,o2,s))
b2.sort(key=lambda t:-t[0]); print(b2[:5])
